# Classify hint questions by type
hint_questions = []
for s in samples:
    q = s['question']
    if 'Hint:' in q and 'option letter' in q.lower():
        hint_questions.append(s)

print(f\"Total hint questions: {len(hint_questions)}\")
print()

# Classify by question pattern
patterns = {}
for s in hint_questions:
    q = s['question']
    # Extract the actual question (after \"Question:\")
    q_match = re.search(r'Question:\\s*(.+?)(?:\\n|"'$)'"', q)
    if q_match:
        actual_q = q_match.group(1).strip()
    else:
        actual_q = q.split('\\n')[2] if len(q.split('\\n')) > 2 else q

    first_word = actual_q.split()[0].lower() if actual_q.split() else \"\"

    # Categorize
    if 'difference' in actual_q.lower():
        cat = 'difference'
    elif 'total' in actual_q.lower() or 'how many' in actual_q.lower():
        cat = 'counting/total'
    elif 'average' in actual_q.lower() or 'mean' in actual_q.lower():
        cat = 'average'
    elif 'rate' in actual_q.lower() or 'percentage' in actual_q.lower():
        cat = 'rate/percentage'
    elif 'ratio' in actual_q.lower():
        cat = 'ratio'
    elif 'which' in first_word:
        cat = 'which'
    elif 'what is' in actual_q.lower():
        cat = 'what_is'
    else:
        cat = 'other'

    patterns[cat] = patterns.get(cat, 0) + 1
    if cat == 'difference':
        print(f\"  [{cat}] {actual_q[:80]} (answer: {s['answer']})\")

print()
print(\"Hint question categories:\")
for cat, count in sorted(patterns.items(), key=lambda x: -x[1]):
